head.script:
scwin.getDateByFormat = function(format) {
    var today = new Date();
    var m = (today.getMonth() < 9 ? '0' : '') + (today.getMonth() + 1);
    var d = (today.getDate() < 10 ? '0' : '') + today.getDate();
    var y = today.getFullYear();
    var val;
    switch (format) {
        case "Y::M":
            val = y + '::' + m;
            break;
        case "Y/M/D":
            val = y + '/' + m + '/' + d;
            break;
        case "Y/M/D h:m":
            val = y + '/' + m + '/' + d + " 00:00";
            break;
        case "Y/M/D h:m:s":
            val = y + '/' + m + '/' + d + " 00:00:00";
            break;
        case "Y/M":
            val = y + '/' + m;
            break;
    }
    console.log(val);
    return val;
}

scwin.checkVal1 = function() {
    return WebSquare.wUnit.getDomById('inputCalendar2_input').value == scwin.getDateByFormat('Y::M');
}
scwin.checkVal2 = function() {
    return WebSquare.wUnit.getDomById('inputCalendar1_input').value == scwin.getDateByFormat('Y/M/D');
}
scwin.checkVal3 = function() {
    return WebSquare.wUnit.getDomById('inputCalendar3_input').value == scwin.getDateByFormat('Y/M/D h:m');
}
scwin.checkVal4 = function() {
    return WebSquare.wUnit.getDomById('inputCalendar4_input').value == scwin.getDateByFormat('Y/M/D h:m:s');
}
scwin.checkVal5 = function() {
    return WebSquare.wUnit.getDomById('inputCalendar5_input').value == scwin.getDateByFormat('Y/M');
}
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "1000");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('inputCalendar2_img').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getJq('.w2calendar_header_btn_ok')[0].click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('inputCalendar1_img').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getJq('.w2calendar_selected')[1].click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('inputCalendar3_img').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getJq('.w2calendar_time_confirm')[0].click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('inputCalendar4_img').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getJq('.w2calendar_time_confirm')[1].click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('inputCalendar5_img').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getJq('.w2calendar_header_btn_ok')[1].click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('inputCalendar5_input').blur()");
    WebSquare.wUnit.addCommand("pause", "500");

    WebSquare.wUnit.addCommand("assert", "scwin.checkVal1()", "true");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal2()", "true");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal3()", "true");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal4()", "true");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal5()", "true");
    WebSquare.wUnit.addCommand("pause", "1000");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();
